{
  "title": "解谜石碑",
  "scene": "石碑上雕刻着古老的符文，周围的草丛中偶尔有小动物出没。小山上空荡荡的，只有一座古老的石碑矗立在中央。石碑上的符文似乎在低语，似乎在等待着玩家的到来。",
  "goal": "找到解除迷雾的方法。",
  "clue": "石碑上的符文与草丛中的小动物有关。",
  "choices": [
    {"id": "A", "text": "触摸石碑", "outcome": "石碑上的符文光芒一闪，似乎有所反应，但没有明显的改变。", "result": "partial", "next": "retry"},
    {"id": "B", "text": "观察草丛", "outcome": "发现草丛中有几行细微的脚印，与石碑上的某些符文形状相似，但不完全对。仔细观察后，玩家注意到脚印中似乎隐藏着一个密码，与符文中的某个图案完全吻合。", "result": "success", "next": "next_level"},
    {"id": "C", "text": "尝试移动石碑", "outcome": "用力摇晃后，石碑纹丝不动，但玩家发现石碑底部有微弱的发光点，似乎需要某种钥匙才能激活。", "result": "fail", "next": "retry"}
  ]
}
